def generate_sequence(x1, x2):
    """Generates the sequence and returns its length if it terminates, or None if potentially infinite/too long."""
    sequence = [x1, x2]
    a = x1
    b = x2

    MAX_ITERATIONS = 50

    for _ in range(MAX_ITERATIONS):
        # Current terms are a = x_{i-1}, b = x_i

        denominator = a + 1
        numerator = b**2 + 1

        if denominator == 0: # Should not happen since x1, x2 >= 1
            break

        if numerator % denominator != 0:
            # Not an integer, sequence terminates
            break

        x_next = (numerator // denominator) - 1

        if x_next <= 0:
            # Must be a positive integer
            break

        sequence.append(x_next)

        # Shift terms
        a = b
        b = x_next

    return len(sequence)

max_length = 0
best_sequences = {}

# Test initial pairs up to (10, 10)
search_limit = 11 # Test x1, x2 from 1 up to 10

for x1 in range(1, search_limit):
    for x2 in range(1, search_limit):
        length = generate_sequence(x1, x2)

        if length > max_length:
            max_length = length
            best_sequences = {(x1, x2): length}
        elif length == max_length:
            best_sequences[(x1, x2)] = length

print(f"Maximum sequence length found after expanded search: {max_length}")
print("Sequences achieving this length:")
for pair, length in best_sequences.items():
    print(f"  (x1, x2) = {pair}, Length = {length}")

